--Create Text_desc
local Text_desc = ccui.Text:create()
Text_desc:ignoreContentAdaptWithSize(false)
Text_desc:setFontName("Font/default.ttf")
Text_desc:setFontSize(42)
Text_desc:setString([[一、每周三8点至下周二20点为一个论剑周期。

二、根据每周二20点的排名状态发送奖励，奖励将于每周三8点开始在人气榜处领取。

